query:
LOAD CSV WITH HEADERS
FROM 'https://raw.githubusercontent.com/lordmin33/Advanced-databases/refs/heads/main/Assignment3/Course_Instances.csv'
AS row

CREATE (:CourseInstance {
  courseCode: row["Course code"],
  studyPeriod: toFloat(row["Study period"]),
  academicYear: row["Academic year"],
  instanceId: row["Instance_id"],
  examiner: row["Examiner"]
});

LOAD CSV WITH HEADERS
FROM 'https://raw.githubusercontent.com/lordmin33/Advanced-databases/refs/heads/main/Assignment3/Course_plannings.csv'
AS row

CREATE (:CoursePlanning {
  course: row["Course"],
  plannedStudents: toInteger(row["Planned number of Students"]),
  seniorHours: toFloat(row["Senior Hours"]),
  assistantHours: toFloat(row["Assistant Hours"])
});

LOAD CSV WITH HEADERS
FROM 'https://raw.githubusercontent.com/lordmin33/Advanced-databases/refs/heads/main/Assignment3/Programme_Courses.csv'
AS row

CREATE (:ProgrammeCourse {
  programmeCode: row["Programme code"],
  studyYear: toInteger(row["Study Year"]),
  academicYear: row["Academic Year"],
  course: row["Course"],
  courseType: row["Course Type"]
});

LOAD CSV WITH HEADERS
FROM 'https://raw.githubusercontent.com/lordmin33/Advanced-databases/refs/heads/main/Assignment3/Programmes.csv'
AS row

CREATE (:Programme {
  programmeName: row["Programme name"],
  programmeCode: row["Programme code"],
  departmentName: row["Department name"],
  director: row["Director"]
});

LOAD CSV WITH HEADERS
FROM 'https://raw.githubusercontent.com/lordmin33/Advanced-databases/refs/heads/main/Assignment3/Registrations.csv'
AS row

CREATE (:Registration {
  courseInstance: row["Course Instance"],
  studentId: row["Student id"],
  status: row["Status"],
  grade: toFloat(row["Grade"])
});

LOAD CSV WITH HEADERS
FROM 'https://raw.githubusercontent.com/lordmin33/Advanced-databases/refs/heads/main/Assignment3/Reported_Hours.csv'
AS row

CREATE (:ReportedHours {
  courseCode: row["Course code"],
  teacherId: row["Teacher Id"],
  hours: toFloat(row["Hours"])
});

LOAD CSV WITH HEADERS
FROM 'https://raw.githubusercontent.com/lordmin33/Advanced-databases/refs/heads/main/Assignment3/Senior_Teachers.csv'
AS row

CREATE (:SeniorTeacher {
  teacherName: row["Teacher name"],
  teacherId: row["Teacher id"],
  departmentName: row["Department name"],
  divisionName: row["Division name"]
});

LOAD CSV WITH HEADERS
FROM 'https://raw.githubusercontent.com/lordmin33/Advanced-databases/refs/heads/main/Assignment3/Students.csv'
AS row

CREATE (:Student {
  studentName: row["Student name"],
  studentId: row["Student id"],
  programme: row["Programme"],
  year: toInteger(row["Year"]),
  graduated: row["Graduated"] = 'True'
});

LOAD CSV WITH HEADERS
FROM 'https://raw.githubusercontent.com/lordmin33/Advanced-databases/refs/heads/main/Assignment3/Teaching_Assistants.csv'
AS row

CREATE (:TeachingAssistant {
  teacherName: row["Teacher name"],
  teacherId: row["Teacher id"],
  departmentName: row["Department name"],
  divisionName: row["Division name"]
});
